            if c == 0:
                ray_cells.update((r, cc) for cc in range(w))
            elif c == w - 1:
                ray_cells.update((r, cc) for cc in range(w))

    # A ray recolors every 2-cell it passes through; it does not recolor
    # the rest of the same-shaped region.
    for r, c in ray_cells:
        if grid[r][c] == 0:
            out[r][c] = 1

    return out
